#!/usr/bin/env node

// Generates lib/icons/kit.generated.ts from a Font Awesome Kit `metadata/icons.json` export.
//
// Usage: generate-kit-icons.mjs [--check] [path/to/icons.json]
//
// --check: only validates the licenses and that the generated file is up to date, writes nothing.

import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

// Paths are resolved from this script's location, so it can be run from any directory
const DEFAULT_SOURCE_PATH = fileURLToPath(new URL('./fa-kit/icons.json', import.meta.url))
const OUTPUT_PATH = fileURLToPath(new URL('../lib/icons/kit.generated.ts', import.meta.url))

// Namespace exported by the generated file for each `svg.<style>` of the kit, and the Font Awesome prefix used to name
// its icon constants (e.g. `fasServer`)
const STYLES = {
  solid: 'fas',
  regular: 'far',
  brands: 'fab',
  custom: 'fak',
}

// "arrow-down-a-z" → "ArrowDownAZ"
const toPascalCase = name =>
  name
    .split('-')
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join('')

// Stable ordering of the generated exports, to keep diffs small when the kit changes
const compare = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

// Every style other than `custom` (our own uploads) must be listed in the icon's `free` array, otherwise it's Font
// Awesome Pro content which must not be committed
function findLicenseViolations(kit) {
  const violations = []

  for (const [iconName, entry] of Object.entries(kit)) {
    for (const style of Object.keys(entry.svg ?? {})) {
      if (style !== 'custom' && !(entry.free ?? []).includes(style)) {
        violations.push(`${iconName}:${style}`)
      }
    }
  }

  return violations
}

// Builds the content of kit.generated.ts: one `IconDefinition` constant per icon and style, then one exported namespace
// per style mapping each `faXxx` name to its constant
function generate(kit) {
  const definitions = []
  const namespaces = Object.fromEntries(Object.keys(STYLES).map(style => [style, new Map()]))

  for (const [iconName, entry] of Object.entries(kit)) {
    for (const [style, svg] of Object.entries(entry.svg ?? {})) {
      const prefix = STYLES[style]

      if (prefix === undefined) {
        throw new Error(`Unsupported style "${style}" for icon "${iconName}"`)
      }

      const variable = `${prefix}${toPascalCase(iconName)}`
      // Same tuple as `IconDefinition` in packages/icon/types.ts, consumed by `normalizeIcon()`
      const iconDefinition = [svg.width, svg.height, svg.path]

      definitions.push(`const ${variable}: IconDefinition = ${JSON.stringify(iconDefinition)}`)

      const namespace = namespaces[style]

      // Export the icon under its name and each of its aliases (e.g. `xmark` is also exported as `faClose`)
      for (const name of [iconName, ...(entry.aliases?.names ?? [])]) {
        const key = `fa${toPascalCase(name)}`

        // Two icons exporting the same name would make the import ambiguous
        if (namespace.has(key)) {
          throw new Error(`Duplicate export "${style}.${key}" (from "${namespace.get(key)}" and "${variable}")`)
        }

        namespace.set(key, variable)
      }
    }
  }

  // Styles without any icon in the kit are not exported
  const exports = Object.entries(namespaces)
    .filter(([, namespace]) => namespace.size > 0)
    .map(([style, namespace]) => {
      const entries = [...namespace].sort(([a], [b]) => compare(a, b)).map(([key, variable]) => `${key}: ${variable},`)

      return `export const ${style} = {\n${entries.join('\n')}\n} as const satisfies Record<string, IconDefinition>`
    })

  const header = [
    '// @generated by scripts/generate-kit-icons.mjs from scripts/fa-kit/icons.json - do not edit',
    `import type { IconDefinition } from '@core/packages/icon/types.ts'`,
  ].join('\n')

  // kit.generated.ts is listed in .prettierignore, this output is committed as is
  return [header, ...definitions.sort(), ...exports].join('\n\n')
}

async function main(args) {
  const check = args.includes('--check')
  const sourcePath = args.find(arg => arg !== '--check') ?? DEFAULT_SOURCE_PATH

  const kit = JSON.parse(await readFile(sourcePath, 'utf8'))

  // Checked before generating, so nothing is written when the kit contains Pro content
  const violations = findLicenseViolations(kit)

  if (violations.length > 0) {
    console.error(`Non-Free (Pro) icon styles found in ${sourcePath}, nothing was written:`)
    violations.forEach(violation => console.error(`  - ${violation}`))
    process.exitCode = 1
    return
  }

  const output = `${generate(kit)}\n`

  if (!check) {
    await writeFile(OUTPUT_PATH, output)
    console.log(`Generated ${OUTPUT_PATH}`)
    return
  }

  // --check mode: fails if kit.generated.ts was not regenerated after updating icons.json, or was edited by hand
  const current = await readFile(OUTPUT_PATH, 'utf8').catch(error => {
    if (error.code === 'ENOENT') {
      return undefined
    }

    throw error
  })

  if (current !== output) {
    console.error(`${OUTPUT_PATH} is out of date, run \`yarn generate-kit-icons\` in @xen-orchestra/web-core`)
    process.exitCode = 1
  }
}

await main(process.argv.slice(2))
